proof.raw_tex:
\begin{lemma}\label{lem:1}
$\displaystyle z_{SALR}(\rho) = \min_{\u \in \calU}\,\, \phi(\u) + \rho\norm{\u}$ . 
\end{lemma}

\begin{proof}
Observe the following inequality which follows immediately from the aforementioned definitions
\begin{align}
    z_{SALR}(\rho) = \min_{\x \in X} f(\x) + \rho\, \norm{\b - \A\,\x} & \leq \min_{\x\in X \cap \Hu} f(\x) + \rho\norm{\u} ,\,\,\,\,\, \forall\,\u \in \calU \nonumber\\
                    & = \phi(\u) + \rho\norm{\u} ,\,\,\,\,\, \forall\,\u \in \calU. \label{eq:1}
\end{align}
Conversely, it holds that $\forall\,\u \in \calU$
\begin{align*}
    \phi(\u) + \rho\norm{\u} & = \min_{\x\in X \cap \Hu} f(\x) + \rho\norm{\u}\\
                             & \leq f(\x) + \rho\norm{\A\x-\b} ,\,\,\,\,\, \forall\,\x\in X\cap \Hu.
\end{align*}
This implies that $ \min_{\u \in \calU} \phi(\u) + \rho \norm{\u} \leq f(\x) + \rho \norm{\A\x - \b} $ $\forall~ x\in X \cap \Hu,\,\forall~\u \in U$ which yields that $ \min_{\u \in \calU} \phi(\u) + \rho \norm{\u} \leq f(\x) + \rho \norm{\A\x - \b} $ $\forall~ \x \in X $. This implies,
\begin{align}
    \min_{\u\in \calU} \phi(\u) + \rho\norm{\u} \leq \min_{\x\in X} f(\x) + \rho\norm{\A\x-\b}. \label{eq:2}
\end{align}
The result follows from \cref{eq:1} and \cref{eq:2}.
\end{proof}

\begin{proposition}\label{prop:2}
Consider the continuous relaxation of MICP, and let the optimal objective value $z_R = \min_{X_R\cap \Ho} f(\x)$ be attained at $\x_R$. 
Let $\blambda_{\A}$ and $\blambda_{\E}$ be the Lagrange multipliers for the constraints $\A\x = \b$ and $\E\x\leq \f$, respectively.\vspace{1mm}
\begin{enumerate}[label = \roman*)]
    \item $\phi(\u) > -\infty$ for all $\u \in \calU$.\vspace{1mm}
    \item If $\exists ~ \boldsymbol{\alpha} \in X_R$ such that $f(\boldsymbol{\alpha}) + \rho\norm{\b-\A\,\boldsymbol{\alpha}}\leq \zIP$ and $\rho > \norm{\blambda_\A}$  then 
        \[
                \norm{\A\,\boldsymbol{\alpha} - \b} \leq \frac{\zIP-z_R}{\rho -\norm{\blambda_{\A}}}.
        \]    
\end{enumerate}
\end{proposition}

\begin{proof}
Consider the Lagrangian function for the continuous relaxation of MICP, i.e. for $\x \in \R^n$
\begin{equation*}
    \mathcal{L}(\x,\blambda_{\A},\blambda_{\E}) = f(\x) - \blambda_\A^{\top}(\A\,\x-\b)-\blambda_\E^{\top}(\f-\E\x)
\end{equation*}
As the relaxed problem has only affine constraints strong duality holds (Chapter 5,Section 5.2.3\cite{boyd2004convex}).

 As strong duality holds, the first order necessary (KKT) conditions for $\mathcal{L}(\x,\blambda_{\A},\blambda_{\E})$ can be characterized as
\begin{align}\label{eq:4}
\begin{split}
    \nabla{f(\x)} = \A^{\top}\blambda_\A - \E^{\top}{\blambda_\E}\\
    \blambda_\E^{\top}(\f - \E\x) = 0\\
    \blambda_\A^{\top}(\A\,\x - \b) = 0\\
    \blambda_\E \geq \bz
\end{split}
\end{align}
Observe that $\x_R$ satisfies the system of equations \cref{eq:4}.\\
\begin{enumerate}[label = \roman*)]
    \item To see the result, observe that it suffices to show that $\phi(\u) > -\infty$ for all $\u \in \calU$ such that $\phi(\u) \leq \phi(\bz) = \zIP$. Further, consider the set $F_{\leq}$ defined as,
            $$
                F_{\leq} \define \set{\x \in X}{f(\x) \leq \zIP}.
            $$
            We have for all $\x \in F_{\leq}$, $\zIP \geq f(\x) \geq f(\x_R) + \nabla{f(\x_R)}(\x-\x_R)= z_R + \nabla{f(\x_R)}(\x-\x_R)$. Substituting from \cref{ineq:gradient} we obtain, for all $\x \in F_{\leq}$,
            $$
                \zIP \geq f(\x) \geq z_R + \blambda_{\A}^{\top} (\A\,\x - \b) -  \blambda_\E^{\top} (\E\x -  \f )
            $$
            As $\blambda_{\E} \geq \bz$ and $\x \in X_R$,
            \begin{align*}
                \zIP \geq f(\x) & \geq z_R + \blambda_{\A}^{\top} (\A\,\x - \b)\\
                & \geq z_R - \norm{\blambda_{\A}}\norm{(\A\,\x - \b)}\\
                & = z_R - \norm{\blambda_{\A}}\norm{\u} > -\infty.
            \end{align*}
            Since $f(\x) > -\infty$ for all $\x \in F_{\leq}$, the result follows.\\
    \item Since we have for $\boldsymbol{\alpha}\in X_R$, $f(\boldsymbol{\alpha}) + \rho\norm{\A\,\boldsymbol{\alpha} - \b} \leq  \zIP$; convexity of $f$ yields,
            \begin{align}
                f(\x_R)+ \nabla{f(\x_R)}^{\top}(\boldsymbol{\alpha}-\x_R) +\rho \norm{\A\,\boldsymbol{\alpha} - \b} &\leq \zIP , \text{ i.e.,}\nonumber \\
                z_R+ \nabla{f(\x_R)}^{\top}(\boldsymbol{\alpha}-\x_R) +\rho \norm{\A\,\boldsymbol{\alpha} - \b} &\leq \zIP. \label{ineq:1}
            \end{align}
            It follows from strong duality that
            \begin{align}
            \nabla{f(\x_R)}^{\top}(\x-\x_R) &= \blambda_{\A}^{\top} \A(\x - \x_R) -\blambda_\E^{\top} \E(\x-\x_R)\nonumber\\
             &= \blambda_{\A}^{\top} (\A\,\x - \b) -  \blambda_\E^{\top} (\E\x -  \f ). \label{ineq:gradient}
            \end{align}
            Substituting in \cref{ineq:1}, we obtain
            \begin{align*}
            z_R+ \blambda_{\A}^{\top} (\A\,\boldsymbol{\alpha} - \b) +  \blambda_\E^{\top} (\f - \E\boldsymbol{\alpha}) +\rho \norm{\A\,\boldsymbol{\alpha} - \b}  & \leq \zIP .
            \end{align*}
            As $\blambda_{\E} \geq \bz$ and $\boldsymbol{\alpha} \in X_R$, the above inequality can be rewritten as
            % \blambda_{\A}^{\top} (\A\,\x - \b) +   \blambda_\E^{\top} ( \f - \E\x ) +\rho \norm{\A\,\x - \b} & \leq \zIP - z_R\\
            \begin{align}
            \blambda_{\A}^{\top}(\A\,\boldsymbol{\alpha} - \b) + \rho \norm{\A\,\boldsymbol{\alpha} - \b} & \leq \zIP - z_R \label{ineq:2}
            \end{align}
            Using Cauchy Schwarz inequality in \cref{ineq:2} yields for all $\x \in X_R$,
            \begin{align*}
                -\norm{\blambda_\A}\,\norm{\A\,\boldsymbol{\alpha} - \b} + \rho\,\norm{\A\,\boldsymbol{\alpha} - \b} \leq \zIP - z_R\\
            (\rho - \norm{\blambda_\A})\norm{\A\,\boldsymbol{\alpha} - \b}\leq \zIP - z_R\\
            \norm{\A\,\boldsymbol{\alpha} - \b} \leq \frac{\zIP-z_R}{\rho - \norm{\blambda_\A}}.
            \end{align*}
\end{enumerate}
\end{proof}

\begin{corollary}\label{cor:3}
Consider the set $U_\rho = \set{\u \in \calU}{\phi(\u) + \rho\norm{\u} \leq \phi(\bz)}$. If $\rho > \norm{\blambda_{\A}}$ then for all $\u \in U_\rho$, $$\norm{\u} \leq \frac{\zIP-z_R}{\rho -\norm{\blambda_\A}}.$$
\end{corollary}

\begin{proof}
If for any $~ \u \in U_{\rho},~\exists~ \x \in X\cap H_{\u}$ such that $f(\x) + \rho\norm{\A\x - \b} \leq z_{IP}$, the result follows from \Cref{prop:2}. Alternatively, if $f(\x) + \rho\norm{\A\x - \b} > z_{IP}\,\, \forall~ \x \in X\cap H_{\u}$ for some $\u \in U_{\rho}$. 
\begin{align*}
\phi(\u) + \rho(\norm{\u}) =  \inf_{X\cap H_{\u}} f(\x) + \rho\norm{\A\x - \b} \geq z_{IP}
\end{align*} 
If \(\inf_{X\cap H_{\u}} f(\x) + \rho\norm{\A\x - \b} > z_{IP}\) then $\u \not\in U_{\rho}$ leading to a contradiction. If \(\inf_{X\cap H_{\u}} f(\x) + \rho\norm{\A\x - \b} = z_{IP}\) and there exists an \(\x \in X\cap H_{\u}\) such that \(f(\x) + \rho \norm{\A\x - \b} = z_{IP}\) then the 
result follows from \cref{prop:2}. If there doesn't exist \(\x \in X\cap H_{\u}\) such that \(f(\x) + \rho\norm{\A\x - \b}  = z_{IP}\) then one can find a sequence of \(\x_{p}\) such that the follows holds
\begin{align*}
    f(\x_{p}) + \rho \norm{\A\x_p - \b} \leq z_{IP} + \frac{1}{p} \text{ (From definition of infimum)}\\
\end{align*}
Let \(\x_R\) be the optimal solution of the optimization program \(\inf_{\x \in F_R} f(\x)\). Since we are minimizing a convex function over a rational polyhedron the KKT conditions hold as follows.
\begin{align*}   
\nabla{f(\x_{R})} = \A^{\top}\blambda_\A - \E^{\top}{\blambda_\E}\\
    \blambda_\E^{\top}(\f - \E\x_R) = 0\\
    \blambda_\A^{\top}(\A\,\x_R - \b) = 0\\
    \blambda_\E \geq \bz
\end{align*}
\begin{align*} 
    f(\x_R)+ \nabla{f(\x_R)}^{\top}(\x_{p}-\x_R) +\rho \norm{\A\,\x_p - \b} &\leq \zIP + \frac{1}{p}\text{ (Convexity)}\\
    z_{R} + \blambda_{\A}^{\top} (\A\,\x_p - \b) +  \blambda_\E^{\top} (\f - \E\x_p) +\rho \norm{\A\,\x_p - \b} &\leq \zIP + \frac{1}{p}\\
    % (\rho - \norm{\blambda_{\A}}) \norm{\u} &\leq \frac{\zIP - z_{R}}{\rho - \norm{\blambda_\A}} + \frac{1}{p(\rho - \norm{\blambda_{\A}})}\\
    \norm{\u} &\leq \frac{\zIP - z_{R}}{\rho - \norm{\blambda_{\A}}} + \frac{1}{p(\rho - \norm{\blambda_{\A}})}
\end{align*}
where the last inequality follows from non-negativity of $\blambda_\E$ and $(\f - \E\x_p).$ As \(p\) is arbitrary, we have as $p \to \infty$,
\begin{align*}
    \norm{\u} &\leq \frac{\zIP - z_{R}}{\rho - \norm{\blambda_{\A}}}
\end{align*}
\end{proof}

\begin{corollary}\label{cor:4}
Consider the set $\,\ocalU \define \set{\u \in \calU}{\phi(\bz) \geq \phi(\u)}$. For $\alpha \geq 0$, $\phi(\bz) \leq \phi(\u) + \alpha$ $\forall \,\u \in \calU$ if $\phi(\bz) \leq \phi(\u) + \alpha$ $\forall \,\u \in \ocalU$.
\end{corollary}

\begin{proof}
    For $\u \in \calU\setminus\ocalU$, $\phi(\bz) < \phi(\u) \leq \phi(\u) + \alpha$. The result follows.
\end{proof}

\begin{lemma}\label{lem:3}
If there exist $\delta, \kappa > 0$ such that  $\phi(\bz) \leq \phi(\u) + \kappa \norm{\u}$ for all $\u \in \mathcal{N}_{\delta}(\bz) \cap \calU$,  then there exists $0 < \rho^{*} < \infty$ such that $z_{SALR}(\rho) = \zIP$ for all $\rho > \rho^{*}$.
\end{lemma}

\begin{proof}
Observe that, for $\rho > 0$ it suffices to consider $\u \in U_\rho$. We have, from \cref{lem:1} 
$$ z_{SALR}(\rho) = \min_{\u\in \calU} \phi(\u) + \rho \norm{\u}.$$
It follows that,
\begin{align*}
    z_{SALR}(\rho) = \min_{\u\in U_\rho}\phi(\u) + \rho \norm{\u}
\end{align*}
\cref{prop:2} yields that for $\rho > \norm{\blambda_{\A}}$ and $\u \in U_{\rho}$, $\norm{\u}$ is bounded. Thus, we have
\begin{equation*}
    z_{SALR}(\rho) = \min_{\u \in \mathcal{N}_{\delta_{\rho}}(\bz) \cap\, U_\rho}\phi(\u) + \rho \norm{\u} 
\end{equation*}
where $\displaystyle\delta_{\rho} = \frac{\zIP - z_R}{\rho -\norm{\blambda_{\A}}}$. From \cref{prop:2} we see that as $\rho \to \infty,\, \mathcal{N}_{\delta_{\rho}}(\bz) \cap U_\rho \to \{\bz\}$. If $\exists$ $\delta > 0$, and $0 < \kappa < \infty$ such that $\phi(\bz) \leq \phi(\u) + \kappa \norm{\u}$ for all $\u \in \mathcal{N}_{\delta}(\bz) \cap U_\rho$, it follows that,
\begin{align}
    \min_{\u\in \mathcal{N}_{\delta}(\bz)\cap\, U_\rho} \phi(\u) + \kappa \norm{\u} = \phi(\bz) = \zIP\label{eq:9}
\end{align}
Alternatively, we can increase $\rho$ such that $\forall\, \u \in U_\rho$, $\norm{\u} \leq \dfrac{\zIP - z_R}{\rho -\norm{\blambda_{\A}}} < \delta$.  Rearranging the terms, we obtain $\rho > \norm{\blambda_\A} + \frac{\zIP - z_R}{\delta}$.  It follows from \cref{eq:9} that for any choice of $\displaystyle \rho > \max\left\{\kappa, \norm{\blambda_\A} + \frac{\zIP - z_R}{\delta}\right\}$, we have  
\begin{align*}
    z_{SALR}(\rho) = \min_{\u\in \mathcal{N}_{\delta_{\rho}}(\bz) \cap\, U_\rho} \phi(\u) + \rho \norm{\u} = \zIP.
\end{align*}
\end{proof}

\begin{lemma}\label{lem:6}
If the integer variables are bounded, then the value function $\displaystyle \hat{\phi}(\u) = \min_{i \in [k]} \Phi(\u,\x^{(i)}_I)$ is lower semi-continuous at $\bz$.
\end{lemma}

\begin{proof}
Observe that for $\u \in \calU, \x^{(i)}_I \in S_I$, $\Phi(\u,\x^{(i)}_I)$ is lower semi-continuous at ${\u}$ if and only if strong duality holds at ${\u}$ [Proposition 6.5.2,\cite{bertsekas2003convex}]. If for some $\x^{(i)}_I$, $\Phi(\bz, \x^{(i)}_I) < +\infty$ then $\Phi(\u, \x^{(i)}_I)$ is lower semi-continuous at $\u = \bz$ due to Slater Condition (in case of affine constraints only feasibility is required). On the contrary, $\Phi(\bz,\x^{(i)}_I) = + \infty$ implies that the polyhedron $P = \set{\x \in \R^{n_2}}{\tilde{\A}\x = \tilde{\b}, \,\,\x \geq \bz}$ is empty, where
\begin{align*}
    \tilde{\A} = \begin{pmatrix}
      {\A}_C & -{\A}_C & \bz\\
      {\E}_C & -{\E}_C & \mathbb{I}
    \end{pmatrix},~
    \x = \begin{pmatrix}
    \x_C^+\\
    \x_C^-\\
    \s
    \end{pmatrix},~
    \tilde{\b} = \begin{pmatrix}
     {\b}  -{\A}_I{\x}^{(i)}_I\\
     {\f} - {\E}_I{\x}^{(i)}_I
    \end{pmatrix}.
\end{align*}
Let $C$ be the closed convex cone spanned by the columns of $\tilde{\A}$. If $P = \emptyset$ then $\tilde{\b} \not\in C$. Since $C$ is a closed, 
$\exists\,\,\delta_{i} > 0$ such that $\mathcal{N}_{\delta_i}(\tilde{\b}) \cap C = \emptyset$. Consider $\u \in \R^m \cap \mathcal{N}_{\delta_i}(\bz)$, then $\tilde{\b} + \begin{pmatrix}\u\\\bz\end{pmatrix} \not \in C$.

For $J = \set{i\in [k]}{\Phi({\x}^{(i)}_I,\bz) < \infty}$, define $\displaystyle\delta_{\min} \define \min_{i \in [k]\setminus J}\delta_i$.

Consider y such that $y  < \hat{\phi}(\bz)$, it follows that 
\begin{align*}
    y & < \hat{\phi}(\bz) < \min_{i \in J}\Phi(\bz,{\x}^{(i)}_I) \leq \Phi(\bz,{\x}^{(i)}_I) .
\end{align*}
However, since every $\Phi({\u},{\x}^{(i)}_I), \, i \in J$ is lower semi-continuous at $\bz$, there exists a $\delta_i > 0$ such that $\Phi({\u},{\x}^{(i)}_I) > y$ for every ${\u} \in \mathcal{N}_{\delta_i}(\bz), \, i \in J$. Let $\delta'_{\min} = \min(\delta_i),\, i \in J$ and $\delta'' = \min(\delta_{\min},\delta'_{\min})$. This means that for every ${\u} \in \mathcal{N}_{\delta''}(\bz)$ $\Phi({\u},{\x}^{(i)}_I) > y \implies  \hat{\phi}({\u}) > y$. The result follows.
\end{proof}

Consider $\ocalU$ as defined in \cref{cor:4}, it follows from \cref{lem:6} that $\lim_{\u\to \bz} \hat{\phi}(\u) = \hat{\phi}(\bz)$ where $\u \in \ocalU$. Now, for every $\epsilon > 0$ there exists a $\delta > 0$ such that
\begin{equation*}
   \abs{\hat{\phi}(\u) - \hat{\phi}(\bz)} < \epsilon\,\, \forall \u\,\, \in \mathcal{N}_{\delta}(\bz) \cap \ocalU
\end{equation*}
\begin{lemma}\label{lem:8}
Consider the value function $\hat{\phi}(\u)$ as defined earlier for $\textup{\MICP}_\u$. There exists a $\delta > 0$ such that for all $\u \in \mathcal{N}_\delta(\bz) \cap \ocalU$, $\displaystyle \hat{\phi}(\u) = \min_{\x_I\in S_{=}^{\bz}} \Phi(\u,\x_I)$ where $S_{=}^{\bz} = \set{\x_I \in S_I}{\Phi(\bz,\x_I) = \hat{\phi}(\bz)}$
\end{lemma}

\begin{proof}
We can partition the index sets corresponding to solutions of $\CPui$ into two sets, 
$$
S_{>}^{\bz} = \set{\x_I\in S_I}{\Phi(\bz,\x_I) > \hat{\phi}(\bz)} \text{ and } S_{=}^{\bz} = \set{\x_I\in S_I}{\Phi(\bz,\x_I) = \hat{\phi}(\bz)}.
$$
For each $\x^{(i)}_I \in S_I$, define $ \overline{\calU}_i=\set{\u \in \calU}{\Phi({\u},\x^{(i)}_I)\leq \Phi(\bz,\x^{(i)}_I)} $. If there is no limiting sequence to ${\bz}$ in $\overline{\calU}_i$ then there exists a neighbourhood $\delta_i$ such that $\mathcal{N}_{\delta_i}(\bz) \cap \overline{\calU}_i = \emptyset$. Alternatively, if there does exist a limiting sequence to $\bz$ and since $\Phi({\u},{\x}_I^{(i)})$ is lower semi-continuous,
\begin{equation*}
    \lim_{{\u}\to \bz} \Phi({\u},{\x}^{(i)}_I) = \Phi(\bz,{\x}^{(i)}_I)
\end{equation*}
Thus, for every $\epsilon_i > 0$ there exists a $\delta_i > 0$ such that
\begin{align*}
    \abs{\Phi({\u},{\x}^{(i)}_I) - \Phi(\bz,{\x}^{(i)}_I)}< \epsilon_i \,\,\,\,\, \forall \,\,\,\,{\u}\in \overline{\calU}_i\cap \mathcal{N}_{\delta_i}(\bz)
\end{align*}
For $\x^{(i)}_I \in S_{>}^{\bz}$, let $\epsilon_i = \Phi(\bz,{\x}^{(i)}_I) - \hat{\phi}(\bz)$. Assuming that $\Phi(\bz,{\x}_I^{(i)})$ is finite, $\forall$ $\u \in \overline{\calU}_i\cap \mathcal{N}_{\delta_i}(\bz)$
\begin{align*}
    \Phi(\bz,{\x}^{(i)}_I) - \Phi({\u},{\x}_I^{(i)}) & <  \Phi(\bz,{\x}^{(i)}_I) - \hat{\phi}(\bz)\\
    \hat{\phi}(\bz) & < \Phi({\u},{\x}^{(i)}_I)
\end{align*}
Thus, for all $\x^{(i)}_I\in S_{>}^{\bz}$ there exists a $\delta_i$ such that $\Phi({\u},{\x}_I^{(i)}) > \hat{\phi}(\bz)$. Assigning $\delta_{\min} = \min_{\x^{(i)}_I\in S^{\bz}_{>}} \delta_i$ yields $\displaystyle \hat{\phi}({\u}) = \min_{\x_I\in S^{\bz}_{=}}\Phi({\u},{\x}_I)$ for every $\u \in \mathcal{N}_{\delta_{\min}}(\bz)\cap \overline{\calU}$.
\end{proof}

\begin{lemma}\label{lem:9}
Consider the value function $\hat{\phi}(\u)$ as defined earlier for $\textup{\MICP}_\u$. There exists a $\delta > 0$ and $0 < \Gamma< \infty$ such that for every $ \u\in \mathcal{N}_{\delta}(\bz)\cap \calU$, $$\hat{\phi}(\bz)\leq \hat{\phi}(\u) + \Gamma\norm{\u}.$$
\end{lemma}

\begin{proof}
Consider $S^{\bz}_{=}$ as defined in \cref{lem:8}. Analogously, define $$S_{=}^{\u} \define \set{\x_I\in S_{=}^{\bz}}{\Phi(\u,\x_{I}) = \hat{\phi}(\u)}.$$ For $\x^{(i)}_I \in S^{\u}_{=}$, the first order necessary conditions for optimality (KKT conditions) for $\CPui$ can be expressed as, %For  writing the KKT conditions\\
\begin{align}\label{eq:32}
\begin{split}
    \nabla_{C}{f(\x_I^{(i)},\x_C}) & = \A^\top_C\blambda^{\u(i)}_{\A_C} - \E_C^\top\blambda^{\u(i)}_{\E_C}\\
    \A_C\x_C & = \b + \u - \A_I\x^{(i)}_I\\
    \E_C\x_C+\E_I\x^{(i)}_I & \leq \f\\
    {\blambda^{\u(i)}_{\E_C}}^\top(\f - \E_C\x_C - \E_I\x^{(i)}_I) & = \bz\\
    {\blambda^{\u(i)}_{\A_C}}^\top(\A_C\x_C + \A_I\x^{(i)}_I - \b - \u) & = \bz\\
    {\blambda^{\u(i)}_{\E_C}} & \geq \bz
\end{split}
\end{align}
Define $H^{(j)}_{\u} = \set{\x_C \in \R^{n_2}}{\A_C\x_C = \b +\u- \A_I\x^{(j)}_I}$. Let $(\x_I^{(j)},\x_C) \in X \cap H^{(j)}_{\u}$ where $\x_I^{(j)} \in S_{=}^{\u}$.
Additionally, let the corresponding Lagrange multipliers at $\u = \bz$ for $\x^{(j)}_I$ be $\blambda^{(j)}_{\A_C}$ and $\blambda^{(j)}_{\E_C}$.
\begin{align*}
    f(\x^{(j)}_I,\x^{\u}_C) & \geq f(\x^{(j)}_I,\x^{\bz^*}_C) +  \nabla_C{f(\x_I^{(j)}}\x^{\bz*}_C)^{\top}(\x^{\u}_C -  \x^{\bz*}_C )\\ 
    & \hspace{3cm}+\nabla_I{f(\x_I^{(j)}}, \x^{\bz*}_C)^{\top}(\x^{(j)}_I -  \x^{(j)}_I)\\
    & = f(\x^{(j)}_I,\x^{\bz^*}_C) + ( \blambda^{(j)^\top}_{\A_C}\A_C - \blambda^{(j)^\top}_{\E_C}\E_C) (\x^{\u}_C -  \x^{\bz*}_C)\\
    & = f(\x^{(j)}_I,\x^{\bz^*}_C) +  \blambda^{(j)^\top}_{\A_C}\A_C(\x^{\u}_C -  \x^{\bz*}_C) - \blambda^{(j)^\top}_{\E_C}\E_C (\x^{\u}_C -  \x^{\bz*}_C)\\
    & = f(\x^{(j)}_I,\x^{\bz^*}_C) +  \blambda^{(j)^\top}_{\A_C}(\A_C \x^{\u}_C -  \A_C \x^{\bz*}_C) - \blambda^{(j)^\top}_{\E_C}(\E_C \x^{\u}_C -  \E_C \x^{\bz*}_C)\\
    & = f(\x^{(j)}_I,\x^{\bz^*}_C) +  \blambda^{(j)^\top}_{\A_C}(\b+\u-\A_I\x^{(j)}_I - \b + \A_I\x^{(j)}_I)\\ 
    & \hspace{3cm}-\blambda^{(j)^\top}_{\E_C}(\E_C \x^{\u}_C -  \f + \E_I\x^{(j)}_I)
\end{align*}
where the equalities follow from the set of equations \cref{eq:32}. Furthermore, observe that since $\blambda^{(j)^\top}_{\E_C} \geq \bz$ and $\E_C\x^{\u}_C + \E\x^{(j)}_I \leq \f$, it follows that 
\begin{align*}
   f(\x^{(j)}_I,\x^{\u}_C) & \geq f(\x^{(j)}_I,\x^{\bz^*}_C) +  \blambda^{(j)^\top}_{\A_C}(\u), \\
      \inf_{X\cap H^{(j)}_{\u}}f(\x^{(j)}_I,\x^{\u}_C) & \geq f(\x^{(j)}_I,\x^{\bz^*}_C) +  \blambda^{(j)^\top}_{\A_C}(\u), \text{ i.e.,}\\
   \hat{\phi}({\u)} & \geq \hat{\phi}(\bz) +  \blambda^{(j)^\top}_{\A_C}(\u)
\end{align*}
Rearranging the terms in the above inequality,     $-\blambda^{(j)^\top}_{\A_C}\u \geq \hat{\phi}(\bz) - \hat{\phi}({\u)}$. As $\hat{\phi}(\bz)\geq \hat{\phi}(\u)$ $\forall\,\,\, \u \in \ocalU$, using Cauchy-Schwarz on the left-hand side of the inequality,
\begin{align*}
    \norm{\blambda^{(j)}_{\A_C}}\cdot\norm{\u} \geq \hat{\phi}(\bz) - \hat{\phi}({\u)} .
\end{align*}
Defining $\Gamma = \max_{i\in S^{\bz}_{=} }{\norm{\blambda^{(j)}_{\A_C}}}$ yields
$$
    \hat{\phi}(\bz) - \hat{\phi}(\u)\leq \Gamma\norm{\u}\,\,\forall\,\, \u \in \mathcal{N}_{\delta}(\bz)\cap\ocalU
$$
where $\delta = \delta_{min}$ as defined in the proof of \cref{lem:8}. The result follows.
\end{proof}

This completes the proof of \Cref{thm:3}(a). In the following section we present some cases where an equivalence can be established between (MICP) and (MICP) with bounded integer variables. In particular, we highlight that  if the objective function $f$ satisfies $\rec(f)\cap\rec(F_R)\setminus\{\bz\} = \emptyset$, then there exists $M < \infty$ such that the following equivalence holds.
$$ \min\set{f(\x)}{\A\x = \b, \x \in X} = \min\set{f(\x)}{\A\x = \b, \norm{\x}_{\infty} \leq M, \x \in X}.$$ Observe that if $f$ is $\mu$-strongly convex, then $\rec(f) = \emptyset$, as the level sets of $f$ are bounded. 


\begin{lemma}\label{lem:15}
Let  $\delta > 0$, and let $\u \in \mathcal{N}_{\delta}(\bz)\cap \ocalU$. Define
$$
    S^\u \define  \set{\x \in X \cap \Hu}{ f(\x) \leq \zIP}.
$$
If \textup{\MICP} is feasible ($F \neq\emptyset$) and bounded and the recession cone of $f$ and recession cone of $F_R$, the feasible set of continuous relaxation of \textup{\MICP}, have no common non-zero directions of recession, then  $S^\u$ is bounded.
\end{lemma}

\begin{proof}
Consider $\u \in \mathcal{N}_{\delta}(\bz)\cap \ocalU$. Since $\norm{\u}_\infty \leq \norm{\u} < \delta$ we have $\norm{\b - \A\x}_{\infty} < \delta$, $\forall\,\x \in X \cap \Hu$. Alternatively, $\forall\,\x \in X \cap \Hu$, $-\1\delta < {\b} - \A\x < \delta\1$. Define, for $\u \in \mathcal{N}_{\delta}(\bz)\cap \ocalU$
\begin{align*}
  S^\u \define  \set{\x \in X \cap \Hu}{ f(\x) \leq \zIP}
\end{align*}
Additionally, consider
\begin{align*}
   S = \set{\x\in X_R}{\begin{Bmatrix}
                                    -{\1}\delta \leq {\b} - \A\x \leq {\1}\delta \\
                                    f(\x) \leq z_{IP}
                        \end{Bmatrix}}
\end{align*}
%Here ${\u}$ is taken over all feasible polyhedra i.e. this set $\{\A\x = {\b} + {\u},\,\, {\E}\x\leq {\f}\,\, ,\x\in \mathbb{Z}^{n_1}\times \mathbb{R}^{n_2}\}$ is feasible.
Indeed, $S^\u \subseteq S$. Furthermore, $\rec(S) = \rec(F_R) \cap \rec(f)$, and since $\rec(F_R) \cap \rec(f) = \{\bz\}$, it follows that $S$ is compact and consequently $S^\u$ is bounded. In particular, $\norm{\x}_\infty \leq M < \infty$, $\forall$ $\x \in S^\u$. %since MICP is feasible and optimally bounded S'' is non-empty.\\
%This implies that one can prescribe a uniform bound on variables of the problem and hence $\norm{\x_I\norm{\leq M$.
\end{proof}

\begin{corollary}\label{cor:16}
If \textup{\MICP} is feasible ($F \neq\emptyset$) and bounded and the recession cone of $f$ and recession cone of $F_R$, the feasible set of continuous relaxation of \textup{\MICP}, have no common non-zero directions of recession, then for ${\u} \in \mathcal{N}_{\delta}(\bz)\cap \ocalU$, $\phi(\u) = \hat{\phi}(\u)$ i.e.
\begin{optprog*}
    {$\phi(\u) = $ minimize}  & \objective{\hspace{1.3cm}f({\x_I},{\x_C})}\\
    subject to & \hspace{0cm} \A_I\,\x_I + \A_C\x_C = \b + \u\\
    & \E_I\x_I + \E_C\x_C \leq \f \hspace{7mm}\\
    & \norm{\x_I}_{\infty}\leq M \hspace{0.5cm}\\
    % & \x_I\in \Z_{+}^{n_1}\hspace{0.4cm}\\ 
     & (\x_I, \x_C) \in \Z^{n_1}\times\R^{n_2}\hspace{0.3cm}
\end{optprog*}
Furthermore, there exists a $\delta > 0$ and $0 < \Gamma < \infty$ such that for every $ \u\in \mathcal{N}_{\delta}(\bz)\cap \calU$, $\phi(\bz)\leq \phi(\u) + \Gamma\norm{\u}$. Additionally, if $f$ is $\mu$-strongly convex and $L$ smooth, then $\Gamma = \mathcal{O}\left(\frac{L\beta\gamma}{\mu}\right)$ where $\displaystyle \beta \define \max_{B \in \mathcal{B}}\norm{B^{-1}}_F$, $\mathcal{B}$ being the set of all possible invertible submatrices of $[\A^T_C \,\, -\A^T_C \hspace{2mm}-{\E}^T_C]$ and $\gamma$ depends on $f(\bz)$, $\norm{\nabla{f(\bz)}}$ and $f(\bar{\x})$ for any $\bar{\x} \in F$.
\end{corollary}

\begin{proof}
\Cref{lem:15}, along with \cref{lem:8,lem:9} readily implies that $\phi(\u) = \hat{\phi}(\u)$ and there exists a $\delta > 0$ and $0 < \Gamma < \infty$ such that for every $ \u\in \mathcal{N}_{\delta}(\bz)\cap \calU$, $\phi(\bz)\leq \phi(\u) + \Gamma\norm{\u}$.

To see the explicit bound on $\Gamma$, recall the stationarity condition from set of equations \cref{eq:32} at $\u = \bz$.
\begin{align}\label{eq:stationarity}
\begin{split}
    \nabla_{C}{f(\x_I^{(i)},\x_C}) & = \A^T_C(\lambda^{(i)+}_{\A_C} - \lambda^{(i)-}_{\A_C}) - {\E}_C^T\lambda_{{\E}_C}\\
    \lambda_{\E_C}^{\top}(\E\x -\f) &= 0\\
    \lambda^{+}_{\A_C},\lambda^{-}_{\A_C} & \geq \bz\\
     \lambda_{{\E}_C} &\geq \bz
\end{split}
\end{align}

For $(\x_C,\x^{(i)}_I)$ consider the complementary slackness conditions, that is if for some $j\in [m]$, $\E_{j}\x < \f_j$ where $\E_{j}$ is a row of the matrix $\E$ then the corresponding Lagrangian multiplier $\lambda_{\E_j} = 0$. Partition the set $[m]$ into two sets $J = \{J_<,J_=\}$, where $J_<=\set{j\in [m]}{\E_j \x <\f_j}$ and $J_= =\set{j\in [m]}{\E_j \x = \f_j}$.\\

Define $\A_{aug} = [\A^T_C \,\, -\A^T_C \hspace{2mm}-{\E}^{\top}_C]$ and $\A_{aug}^J$ as the sub-matrix which has all the columns of $\A_{aug}$ except the columns $2n_2+J_<$.
 % $\lambda^{(i)+}_{\A_C},\lambda^{(i)-}_{\A_C}$. 
 One possible solution to the system \cref{eq:stationarity} is,
 \begin{align}\label{sol:lambda}
    \begin{pmatrix}
     \lambda^{+}_{\A_C}\\
      \lambda^{-}_{\A_C}\\
      \lambda_{{\E}^{J_{=}}_C}
    \end{pmatrix} = B^{-1} \nabla_C{f(\x^{(i)}_I,\x_C)}
\end{align}
where $B$ is a basis matrix of $\A_{aug}^J$.

Furthermore, let $\lambda_{\A_C} = \lambda^{+}_{\A_C} - \lambda^{-}_{\A_C}$, this implies that 
\begin{align}
    \norm{\lambda_{\A_C}} \leq \norm{\lambda^{+}_{\A_C}} + \norm{\lambda^{-}_{\A_C}} \label{ineq:lambda}    
\end{align}
Let $\x^*$ be an optimal solution to \MICP, i.e. $f(\x^*) = \zIP$. Since $f$ is $\mu$-strongly convex, we have

\begin{align*}
    \frac{\mu}{2} \norm{\x^*}^2 + \nabla{f({\bz)}}^\top\x^*  + f(\bz) & \leq z_{IP}\\
    \frac{\mu}{2} \norm{\x^*}^2 + \nabla{f({\bz)}}^\top\x^* - z_{IP} + f(\bz)& \leq 0\\
    \frac{\mu}{2} \norm{\x^*}^2 - \norm{\nabla{f({\bz)}}}\,\norm{\x^*} - \left(z_{IP} - f(\bz)\right) & \leq 0
\end{align*}
It follows that,
$$
    \norm{\x^*}\leq \frac{\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz})}^2 +2\,\mu\cdot \left(z_{IP} - f(\bz)\right)}}{\mu}
$$
Since $f$ is L-smooth,
\begin{align*}
    \norm{\nabla{f(\x^*)} - \nabla{f(\bz)}} &\leq L\norm{\x^*}\\
    \norm{\nabla{f(\x^*)}} &\leq L\norm{\x^*} + \norm{\nabla{f(\bz)}}
\end{align*}
From \cref{sol:lambda} and \cref{ineq:lambda} we obtain
\begin{align*}
    \norm{\lambda_{\A_C}} & \leq 2\norm{B^{-1}}_F \norm{\nabla{f(\x^*)}}\\
    & \leq 2\norm{B^{-1}}_F\left(L\norm{\x^*} + \norm{\nabla{f(\bz)}}\right)\\
    & \leq 2\beta\left(L\norm{\x^*} + \norm{\nabla{f(\bz)}}\right)
\end{align*}
where $\beta \define \max_{B \in \mathcal{B}}\norm{B^{-1}}_F$ and $\mathcal{B}$ is the set of all possible invertible submatrices of $[\A^T_C \,\, -\A^T_C \hspace{2mm}-{\E}^T_C]$.

\begin{align}
   \norm{\lambda_{\A_C}} & \leq \dfrac{2\beta\left(L\left(\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz})}^2 +2\mu\,\left(z_{IP} - f(\bz)\right)}\right) + \mu\norm{\nabla{f(\bz)}}\right)}{\mu}\nonumber\\
    & \leq  \dfrac{2\beta L}{\mu}\left(2\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz)}}^2 + 2\mu\,\left(f(\bar{\x}) - f(\bz)\right)}\right)\label{ineq:thm3}
\end{align}
where the second inequality follows as $\zIP \leq f(\bar{\x}),$ $\forall\,\bar{\x} \in F$ and $L > \mu$. Combining \cref{ineq:thm3} with the construction of $\Gamma$ in \cref{lem:9}, yields the result.
\end{proof}

\cref{thm:3} follows.

