Consider, to begin with, the following mixed integer convex programming (MICP) problem,
\begin{optprog*}
    {$\zIP = $ minimize}  & \objective{\hspace{3mm}f(\x)}\\
   \textbf{(MICP)} \qquad subject to & \A\,\x\,= \b\\
     & \x \in X \hspace{1mm}
\end{optprog*}
where $X:= \set{\x\in \Z^{n_1}\times\R^{n_2}}{\E\x\leq \f}$ is a polyhedral mixed integer set, $f:\R^n \mapsto \R$ is a real valued convex function, $\A,\E$ and $\b,\f$ are full rank matrices and vectors of appropriate dimensions, respectively. Through out the remainder of this discussion we assume that the matrices $\A, \E$ are rational matrices and $\b, \f$ are rational vectors and $f(\cdot)$ is differentiable. We further assume that both MICP and MICP's continuous relaxation are feasible and the corresponding optimal solutions exist.\\

Consider the Lagrangian relaxation of the MICP,
\begin{equation*}
    \textbf{(LR)} \hspace{1cm} z^{LR}(\blambda) = \min_{\x \in X} f(\x) + {\blambda}^{\top}(\b - \A\,\x).
\end{equation*}
The corresponding augmented Lagrangian relaxation and augmented Lagrangian dual (\cite{boland2015augmented,gu2020exact}) of the \MICP\, are defined as,
\begin{align*}
    \textbf{(ALR)} \hspace{0.5cm} z_{\rho}^{LR+}(\blambda) & = \min_{\x \in X} f(\x) + {\blambda}^{\top}(\b - \A\,\x) + \rho\, \psi(\b - \A\,\x)\\
    \textbf{(ALD)} \hspace{1cm} z_{\rho}^{LD+} & = \sup_{\blambda\in \R^m}\min_{\x \in X} f(\x) + {\blambda}^{\top}(\b - \A\,\x) + \rho\, \psi(\b - \A\,\x)
\end{align*}

Consider the hyperplane $H_{\u} \define \set{\x\in\R^n}{\A\x = \b + \u}$, and let the corresponding value function associated with {\MICP} be defined as 
\begin{align}
    \phi(\u) = \min\set{f(\x)}{\x \in X\cap\Hu}.\label{def:valuefunction}
\end{align}
In particular, $\zIP = \phi(\bz) = \min_{\x\in X \cap \Ho} f(\x)$. Finally, we define the set $\calU$ as the set of all possible perturbation vectors $\u$ such that the feasible set of \cref{def:valuefunction} is non-empty. In particular, $\calU \define \set{\u\in \R^m}{X \cap \Hu \neq \emptyset}$.

Consider the following mixed integer convex programming problem.
\begin{optprog*}
    {$\hat{\phi}(\u) = $ minimize}  & \objective{\hspace{1.3cm}f({\x_I},{\x_C})}\\
    $\textup{\MICP}_\u$ \qquad subject to & \hspace{0cm} \A_I\,\x_I + \A_C\x_C = \b + \u\\
    & \E_I\x_I + \E_C\x_C \leq \f \hspace{7mm}\\
    & \norm{\x_I}_{\infty}\leq M \hspace{0.5cm}\\
    % & \x_I\in \Z_{+}^{n_1}\hspace{0.4cm}\\ 
    & (\x_I, \x_C) \in \Z^{n_1}\times\R^{n_2}\hspace{0.3cm}
\end{optprog*}
where $0 \leq M < \infty$. Denote by $F_{\u} \define X \cap \Hu \cap S_I $ the feasible region of $\textup{\MICP}_\u$, where the set $S_I = \set{\x_I \in \Z^{n_1}}{\norm{\x_I}_{\infty} \leq M}$ is finite.  As before, we let $S_I = \{\x^{(1)}_I, \x_I^{(2)}, \ldots, \x_I^{(k)}\}$. Using this enumeration we characterize the value functions of the continuous restrictions, parameterized in $\x_I^{(i)},\,i \in [k]$ as,

\begin{optprog*}
    {$\Phi(\u,\x^{(i)}_I) = $ minimize}  & \objective{\hspace{6mm}f(\x^{(i)}_I,\x_C)}\\
    $\CPui$ \qquad subject to & \A_C\,\x_C = \b + \u - \A_I\x^{(i)}_{I}\\
    & \E_C\x_C \leq \f - \E_I\x^{(i)}_{I}\hspace{8mm}\\
     & \x_C \in \R^{n_2}\hspace{1.8cm}
\end{optprog*}
where $\Phi(\u,\x^{(i)}_I)$ is the value function of $\CPui$, a continuous convex  optimization problem. Since the constraints of $\CPui$ are linear, Slater's condition holds and therefore the value function is lower semi-continuous.

\begin{theorem}\label{thm:3}
Consider the following mixed integer convex programming problem,
\begin{optprog*}
    minimize  & \objective{\hspace{1cm}f({\x_I},{\x_C})}\\
    \textup{\MICP} \hspace{2mm} subject to & \hspace{0cm} \A_I\,\x_I + \A_C\x_C = \b\hspace{6.5mm}\\
    & \E_I\x_I + \E_C\x_C \leq \f \hspace{7mm}\\
    % & \norm{\x_I}_{\infty}\leq M \hspace{0.5cm}\\
    % & \x_I\in \Z_{+}^{n_1}\hspace{0.4cm}\\ 
     & (\x_I, \x_C) \in \Z^{n_1}\times\R^{n_2}\hspace{0.3cm}
\end{optprog*}
Let $F = X\cap \Ho$ denote the feasible region of \textup{\MICP}.\\
\begin{enumerate}[label = (\alph*)]
    \item If $\norm{\x_I}_{\infty}\leq M,$ $\forall\,\x \in F$ then there exists an exact penalty representation for \textup{\MICP}.
    \item If the recession cone of $f$ and recession cone of $F_R$, the feasible set of continuous relaxation of \textup{\MICP}, have no common non-zero directions of recession, then there exists an exact penalty representation for \textup{\MICP}.
\end{enumerate} 
Additionally, if $f$ is $\mu$-strongly convex and $L$ smooth, then the finite penalty parameter $\rho = \mathcal{O}\left(\frac{L\beta\gamma}{\mu}\right)$ where $\displaystyle \beta \define \max_{B \in \mathcal{B}}\norm{B^{-1}}_F$, $\mathcal{B}$ being the set of all possible invertible submatrices of $[\A^T_C \,\, -\A^T_C \hspace{2mm}-{\E}^T_C]$ and $\gamma$ can be explicitly computed given $f(\bz)$, $\norm{\nabla{f(\bz)}}$ and $f(\bar{\x})$ for any $\bar{\x} \in F$.
% $\gamma = \sqrt{f(\bar{\x})}$ for any $\bar{\x} \in F$.\\
\end{theorem}

\begin{lemma}\label{lem:1}
$\displaystyle z_{SALR}(\rho) = \min_{\u \in \calU}\,\, \phi(\u) + \rho\norm{\u}$ . 
\end{lemma}

\begin{proof}
Observe the following inequality which follows immediately from the aforementioned definitions
\begin{align}
    z_{SALR}(\rho) = \min_{\x \in X} f(\x) + \rho\, \norm{\b - \A\,\x} & \leq \min_{\x\in X \cap \Hu} f(\x) + \rho\norm{\u} ,\,\,\,\,\, \forall\,\u \in \calU \nonumber\\
                    & = \phi(\u) + \rho\norm{\u} ,\,\,\,\,\, \forall\,\u \in \calU. \label{eq:1}
\end{align}
Conversely, it holds that $\forall\,\u \in \calU$
\begin{align*}
    \phi(\u) + \rho\norm{\u} & = \min_{\x\in X \cap \Hu} f(\x) + \rho\norm{\u}\\
                             & \leq f(\x) + \rho\norm{\A\x-\b} ,\,\,\,\,\, \forall\,\x\in X\cap \Hu.
\end{align*}
This implies that $ \min_{\u \in \calU} \phi(\u) + \rho \norm{\u} \leq f(\x) + \rho \norm{\A\x - \b} $ $\forall~ x\in X \cap \Hu,\,\forall~\u \in U$ which yields that $ \min_{\u \in \calU} \phi(\u) + \rho \norm{\u} \leq f(\x) + \rho \norm{\A\x - \b} $ $\forall~ \x \in X $. This implies,
\begin{align}
    \min_{\u\in \calU} \phi(\u) + \rho\norm{\u} \leq \min_{\x\in X} f(\x) + \rho\norm{\A\x-\b}. \label{eq:2}
\end{align}
The result follows from \cref{eq:1} and \cref{eq:2}.
\end{proof}

