\begin{proposition}\label{prop:2}
Consider the continuous relaxation of MICP, and let the optimal objective value $z_R = \min_{X_R\cap \Ho} f(\x)$ be attained at $\x_R$. 
Let $\blambda_{\A}$ and $\blambda_{\E}$ be the Lagrange multipliers for the constraints $\A\x = \b$ and $\E\x\leq \f$, respectively.\vspace{1mm}
\begin{enumerate}[label = \roman*)]
    \item $\phi(\u) > -\infty$ for all $\u \in \calU$.\vspace{1mm}

    \item If $\exists ~ \boldsymbol{\alpha} \in X_R$ such that $f(\boldsymbol{\alpha}) + \rho\norm{\b-\A\,\boldsymbol{\alpha}}\leq \zIP$ and $\rho > \norm{\blambda_\A}$  then 
        \[
                \norm{\A\,\boldsymbol{\alpha} - \b} \leq \frac{\zIP-z_R}{\rho -\norm{\blambda_{\A}}}.
        \]    
\end{enumerate}
\end{proposition}

\begin{proof}
Consider the Lagrangian function for the continuous relaxation of MICP, i.e. for $\x \in \R^n$
\begin{equation*}
    \mathcal{L}(\x,\blambda_{\A},\blambda_{\E}) = f(\x) - \blambda_\A^{\top}(\A\,\x-\b)-\blambda_\E^{\top}(\f-\E\x)
\end{equation*}
As the relaxed problem has only affine constraints strong duality holds (Chapter 5,Section 5.2.3\cite{boyd2004convex}).

 As strong duality holds, the first order necessary (KKT) conditions for $\mathcal{L}(\x,\blambda_{\A},\blambda_{\E})$ can be characterized as
\begin{align}\label{eq:4}
\begin{split}
    \nabla{f(\x)} = \A^{\top}\blambda_\A - \E^{\top}{\blambda_\E}\\
    \blambda_\E^{\top}(\f - \E\x) = 0\\
    \blambda_\A^{\top}(\A\,\x - \b) = 0\\
    \blambda_\E \geq \bz
\end{split}
\end{align}
Observe that $\x_R$ satisfies the system of equations \cref{eq:4}.\\
\begin{enumerate}[label = \roman*)]
    \item To see the result, observe that it suffices to show that $\phi(\u) > -\infty$ for all $\u \in \calU$ such that $\phi(\u) \leq \phi(\bz) = \zIP$. Further, consider the set $F_{\leq}$ defined as,
            $$
                F_{\leq} \define \set{\x \in X}{f(\x) \leq \zIP}.
            $$
            We have for all $\x \in F_{\leq}$, $\zIP \geq f(\x) \geq f(\x_R) + \nabla{f(\x_R)}(\x-\x_R)= z_R + \nabla{f(\x_R)}(\x-\x_R)$. Substituting from \cref{ineq:gradient} we obtain, for all $\x \in F_{\leq}$,
            $$
                \zIP \geq f(\x) \geq z_R + \blambda_{\A}^{\top} (\A\,\x - \b) -  \blambda_\E^{\top} (\E\x -  \f )
            $$
            As $\blambda_{\E} \geq \bz$ and $\x \in X_R$,
            \begin{align*}
                \zIP \geq f(\x) & \geq z_R + \blambda_{\A}^{\top} (\A\,\x - \b)\\
                & \geq z_R - \norm{\blambda_{\A}}\norm{(\A\,\x - \b)}\\
                & = z_R - \norm{\blambda_{\A}}\norm{\u} > -\infty.
            \end{align*}
            Since $f(\x) > -\infty$ for all $\x \in F_{\leq}$, the result follows.\\
    \item Since we have for $\boldsymbol{\alpha}\in X_R$, $f(\boldsymbol{\alpha}) + \rho\norm{\A\,\boldsymbol{\alpha} - \b} \leq  \zIP$; convexity of $f$ yields,
            \begin{align}
                f(\x_R)+ \nabla{f(\x_R)}^{\top}(\boldsymbol{\alpha}-\x_R) +\rho \norm{\A\,\boldsymbol{\alpha} - \b} &\leq \zIP , \text{ i.e.,}\nonumber \\
                z_R+ \nabla{f(\x_R)}^{\top}(\boldsymbol{\alpha}-\x_R) +\rho \norm{\A\,\boldsymbol{\alpha} - \b} &\leq \zIP. \label{ineq:1}
            \end{align}
            It follows from strong duality that
            \begin{align}
            \nabla{f(\x_R)}^{\top}(\x-\x_R) &= \blambda_{\A}^{\top} \A(\x - \x_R) -\blambda_\E^{\top} \E(\x-\x_R)\nonumber\\
             &= \blambda_{\A}^{\top} (\A\,\x - \b) -  \blambda_\E^{\top} (\E\x -  \f ). \label{ineq:gradient}
            \end{align}
            Substituting in \cref{ineq:1}, we obtain
            \begin{align*}
            z_R+ \blambda_{\A}^{\top} (\A\,\boldsymbol{\alpha} - \b) +  \blambda_\E^{\top} (\f - \E\boldsymbol{\alpha}) +\rho \norm{\A\,\boldsymbol{\alpha} - \b}  & \leq \zIP .
            \end{align*}
            As $\blambda_{\E} \geq \bz$ and $\boldsymbol{\alpha} \in X_R$, the above inequality can be rewritten as
            % \blambda_{\A}^{\top} (\A\,\x - \b) +   \blambda_\E^{\top} ( \f - \E\x ) +\rho \norm{\A\,\x - \b} & \leq \zIP - z_R\\
            \begin{align}
            \blambda_{\A}^{\top}(\A\,\boldsymbol{\alpha} - \b) + \rho \norm{\A\,\boldsymbol{\alpha} - \b} & \leq \zIP - z_R \label{ineq:2}
            \end{align}
            Using Cauchy Schwarz inequality in \cref{ineq:2} yields for all $\x \in X_R$,
            \begin{align*}
                -\norm{\blambda_\A}\,\norm{\A\,\boldsymbol{\alpha} - \b} + \rho\,\norm{\A\,\boldsymbol{\alpha} - \b} \leq \zIP - z_R\\
            (\rho - \norm{\blambda_\A})\norm{\A\,\boldsymbol{\alpha} - \b}\leq \zIP - z_R\\
            \norm{\A\,\boldsymbol{\alpha} - \b} \leq \frac{\zIP-z_R}{\rho - \norm{\blambda_\A}}.
            \end{align*}
\end{enumerate}
\end{proof}

