 One possible solution to the system \cref{eq:stationarity} is,
 \begin{align}\label{sol:lambda}
    \begin{pmatrix}
     \lambda^{+}_{\A_C}\\
      \lambda^{-}_{\A_C}\\
      \lambda_{{\E}^{J_{=}}_C}
    \end{pmatrix} = B^{-1} \nabla_C{f(\x^{(i)}_I,\x_C)}
\end{align}
where $B$ is a basis matrix of $\A_{aug}^J$.

Furthermore, let $\lambda_{\A_C} = \lambda^{+}_{\A_C} - \lambda^{-}_{\A_C}$, this implies that 
\begin{align}
    \norm{\lambda_{\A_C}} \leq \norm{\lambda^{+}_{\A_C}} + \norm{\lambda^{-}_{\A_C}} \label{ineq:lambda}    
\end{align}
Let $\x^*$ be an optimal solution to \MICP, i.e. $f(\x^*) = \zIP$. Since $f$ is $\mu$-strongly convex, we have

\begin{align*}
    \frac{\mu}{2} \norm{\x^*}^2 + \nabla{f({\bz)}}^\top\x^*  + f(\bz) & \leq z_{IP}\\
    \frac{\mu}{2} \norm{\x^*}^2 + \nabla{f({\bz)}}^\top\x^* - z_{IP} + f(\bz)& \leq 0\\
    \frac{\mu}{2} \norm{\x^*}^2 - \norm{\nabla{f({\bz)}}}\,\norm{\x^*} - \left(z_{IP} - f(\bz)\right) & \leq 0
\end{align*}
It follows that,
$$
    \norm{\x^*}\leq \frac{\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz})}^2 +2\,\mu\cdot \left(z_{IP} - f(\bz)\right)}}{\mu}
$$
Since $f$ is L-smooth,
\begin{align*}
    \norm{\nabla{f(\x^*)} - \nabla{f(\bz)}} &\leq L\norm{\x^*}\\
    \norm{\nabla{f(\x^*)}} &\leq L\norm{\x^*} + \norm{\nabla{f(\bz)}}
\end{align*}
From \cref{sol:lambda} and \cref{ineq:lambda} we obtain
\begin{align*}
    \norm{\lambda_{\A_C}} & \leq 2\norm{B^{-1}}_F \norm{\nabla{f(\x^*)}}\\
    & \leq 2\norm{B^{-1}}_F\left(L\norm{\x^*} + \norm{\nabla{f(\bz)}}\right)\\
    & \leq 2\beta\left(L\norm{\x^*} + \norm{\nabla{f(\bz)}}\right)
\end{align*}
where $\beta \define \max_{B \in \mathcal{B}}\norm{B^{-1}}_F$ and $\mathcal{B}$ is the set of all possible invertible submatrices of $[\A^T_C \,\, -\A^T_C \hspace{2mm}-{\E}^T_C]$.

\begin{align}
   \norm{\lambda_{\A_C}} & \leq \dfrac{2\beta\left(L\left(\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz})}^2 +2\mu\,\left(z_{IP} - f(\bz)\right)}\right) + \mu\norm{\nabla{f(\bz)}}\right)}{\mu}\nonumber\\
    & \leq  \dfrac{2\beta L}{\mu}\left(2\norm{\nabla{f(\bz)}} + \sqrt{\norm{\nabla{f(\bz)}}^2 + 2\mu\,\left(f(\bar{\x}) - f(\bz)\right)}\right)\label{ineq:thm3}
\end{align}
where the second inequality follows as $\zIP \leq f(\bar{\x}),$ $\forall\,\bar{\x} \in F$ and $L > \mu$. Combining \cref{ineq:thm3} with the construction of $\Gamma$ in \cref{lem:9}, yields the result.
